class C1:
    def __init__(self, val):
        self.val = val
    def __str__(self):
        return 'node:' + str(self.val)
    def __repr__(self):
        return '<' + 'node' + ' ' + str(self.val) + '>'

obj = C1(-2)
print(str(obj), repr(obj))

class C1:
    def __init__(self, limit):
        self.limit = limit
    def __iter__(self):
        for i in range(self.limit):
            yield i + 14

seq = C1(3)
out = []
for elem in seq:
    out.append(elem)
print(out, list(seq))

